    a_sum = sum(a)
    b_sum = sum(b)

    if a_sum > b_sum:
        print(1)
    elif rez == 0 or a_sum == 0 or (a_sum == n and b_sum == n):
        print(-1)
    else:
        print((b_sum - a_sum + 1) // rez + 1)

if __name__ == "__main__":
    main()

